/* ===================== BÀI 9 · Immediate, register và memory ===================== */
/* Bài 9 · Immediate, register và memory (AMTS-EMB-002-M03-L01, X86-009) — sinh bởi tools/author/mpu8086/l09.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P9=[{"label": "Ví dụ: ba loại toán hạng đưa 1234h vào", "code": "; Ví dụ 1: ba loại toán hạng cùng đưa 1234h vào thanh ghi\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      1234H                   ; ô nhớ DS:0000 chứa 34h, 12h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1234H               ; tức thời: số nằm ngay trong lệnh\n        MOV     BX, AX                  ; thanh ghi: chép bên trong CPU\n        MOV     DX, so                  ; bộ nhớ: đọc word ở DS:0000\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước và nhìn phần Mã máy và chu kỳ: MOV AX, 1234h (B8 34 12, 4 chu kỳ) mang số trong lệnh; MOV BX, AX (2 chu kỳ) chép trong CPU; MOV DX, so (8B 16 00 00, 14 chu kỳ) đọc ô DS:0000 và phần Bộ nhớ tô hai byte 34 12. Đoán trước: sau MOV DX, so, DX bằng bao nhiêu? Đáp án 1234h (byte thấp 34h ở địa chỉ thấp)."}, {"label": "Ví dụ: kích thước do toán hạng quyết định", "code": "; Ví dụ 2: cùng lệnh INC, kích thước do toán hạng quyết định\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DW      00FFH                   ; word: byte FFh rồi byte 00h\ndem     DB      0FFH                    ; byte\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        INC     dem                     ; byte: FFh + 1 = 00h (tràn 8 bit)\n        INC     tong                    ; word: 00FFh + 1 = 0100h\n        MOV     BX, OFFSET tong\n        MOV     BYTE PTR [BX], 7        ; ghi 1 byte: tong = 0107h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "INC dem dịch thành FE 06 (byte), INC tong thành FF 06 (word): cùng tên lệnh, khác bit w. Byte FFh + 1 = 00h, word 00FFh + 1 = 0100h. MOV BYTE PTR [BX], 7 (C6 07 07) chỉ ghi byte thấp của tong nên tong = 0107h. Đoán trước: sau INC tong, word tong bằng bao nhiêu? Đáp án 0100h."}, {"label": "Lỗi: [BX] không cho biết byte hay word", "code": "; Lỗi: con trỏ [BX] không cho biết ghi byte hay word\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DW      00FFH\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, OFFSET tong\n        MOV     [BX], 7                 ; LỖI: ghi 1 byte hay 2 byte?\n; Sửa: MOV BYTE PTR [BX], 7 hoặc MOV WORD PTR [BX], 7\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch có chủ đích: [BX] là con trỏ không mang kiểu, còn 7 vừa byte vừa word, nên trình dịch không chọn được C6 hay C7. Sửa: MOV BYTE PTR [BX], 7 (ghi 1 byte) hoặc MOV WORD PTR [BX], 7 (ghi 2 byte, byte cao = 0). Hai cách cho hai kết quả khác nhau, chỉ người viết biết mình cần cách nào."}, {"label": "Bẫy: so+1 là địa chỉ, không phải giá trị", "code": "; Bẫy: so+1 là ĐỊA CHỈ kế tiếp, không phải giá trị + 1\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DB      10H, 20H                ; so ở DS:0000, ô kế tiếp DS:0001\nkq1     DB      ?\nkq2     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, so+1                ; đọc ô DS:0001 → 20h\n        MOV     kq1, AL\n        MOV     AL, so                  ; đọc giá trị 10h\n        ADD     AL, 1                   ; cộng vào giá trị → 11h\n        MOV     kq2, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "MOV AL, so+1 dịch thành A0 01 00: địa chỉ 0001h, đọc ra 20h chứ không phải 10h + 1. Muốn cộng giá trị: đọc so vào AL rồi ADD AL, 1 (kq2 = 11h). Xem kq1, kq2 ở phần Bộ nhớ. Đoán trước: sau MOV AL, so+1, AL bằng bao nhiêu? Đáp án 20h."}, {"label": "Ví dụ: nội dung và địa chỉ của biến", "code": "; Ví dụ 5: nội dung của biến và địa chỉ của biến\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nten     DB      'AMTS'                  ; 4 byte: độ lệch 0000h…0003h\nso      DW      0ABCDH                  ; biến so ở độ lệch 0004h\ngiaTri  DW      ?\ndiaChi  DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, so                  ; nội dung: AX = ABCDh\n        MOV     giaTri, AX\n        MOV     AX, OFFSET so           ; địa chỉ: AX = 0004h (số tức thời)\n        MOV     diaChi, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "MOV AX, so (A1 04 00, 10 chu kỳ) đọc nội dung ABCDh; MOV AX, OFFSET so (B8 04 00, 4 chu kỳ) nạp số 0004h, không đọc bộ nhớ. Xem giaTri = CD AB, diaChi = 04 00 ở phần Bộ nhớ. Đoán trước: sau MOV AX, OFFSET so, AX bằng bao nhiêu? Đáp án 0004h."}, {"label": "Lỗi: hai toán hạng đều là ô nhớ", "code": "; Lỗi: hai toán hạng đều là ô nhớ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      1234H\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     kq, so                  ; LỖI: không chép ô nhớ sang ô nhớ\n; Sửa: MOV AX, so rồi MOV kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch có chủ đích: 8086 không có lệnh MOV với hai toán hạng bộ nhớ. Sửa bằng thanh ghi trung gian: MOV AX, so rồi MOV kq, AX (2 lệnh, 6 byte, 20 chu kỳ với dạng ngắn của AX)."}, {"label": "Ví dụ: một kết quả, ba chi phí", "code": "; Ví dụ 7: cùng ghi 1000 vào biến, ba chi phí khác nhau\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DW      ?\ny       DW      ?\nz       DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     x, 1000                 ; ô nhớ ← tức thời: 6 byte, 16 ck\n        MOV     AX, 1000                ; 3 byte, 4 ck\n        MOV     y, AX                   ; dạng ngắn riêng của AX: 3 byte\n        MOV     BX, 1000\n        MOV     z, BX                   ; dạng ModR/M: 4 byte, 15 ck\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Ba cách ghi 1000 (03E8h) vào biến word: tức thời thẳng vào ô nhớ 6 byte, 16 chu kỳ; qua AX 3 + 3 = 6 byte, 4 + 10 = 14 chu kỳ; qua BX 3 + 4 = 7 byte, 4 + 15 = 19 chu kỳ. Cách qua AX nhanh nhất vì dùng dạng ngắn A3. Đoán trước: lệnh MOV z, BX tốn bao nhiêu chu kỳ? Đáp án 15 (9 + EA 6)."}];
const sim9=makeX86Sim(document.getElementById("x86-l9"),{id:"s9",presets:P9,file:"BAI9.ASM"});
makeX86Ex(document.getElementById("ex-l9"),sim9,[{"t": "Giá trị và địa chỉ", "d": "Giữ nguyên phần .DATA của code mẫu (biến ten 4 byte, rồi so và pSo kiểu DW). Đọc một phím chữ số 0–9 bằng INT 21h hàm 08h. Ghi giá trị của chữ số vào biến word so (byte cao bằng 0), ghi địa chỉ (offset) của biến so vào biến pSo, rồi in lại phím vừa gõ bằng INT 21h hàm 02h. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: giá trị và địa chỉ\n; Giữ nguyên phần .DATA. Viết tiếp sau dòng đọc phím.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nten     DB      'AMTS'                  ; giữ nguyên: 4 byte trước biến so\nso      DW      0FFFFH                  ; giá trị chữ số, dạng word\npSo     DW      0                       ; địa chỉ (offset) của biến so\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím chữ số vào AL\n        INT     21H\n; Viết code ở đây: so = giá trị chữ số (word),\n; pSo = địa chỉ của so, rồi in lại phím\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "7", "out": "7", "mem": [{"at": "so", "bytes": [7, 0]}, {"at": "pSo", "bytes": [4, 0]}]}, {"in": "0", "out": "0", "mem": [{"at": "so", "bytes": [0, 0]}, {"at": "pSo", "bytes": [4, 0]}]}, {"in": "9", "out": "9", "mem": [{"at": "so", "bytes": [9, 0]}, {"at": "pSo", "bytes": [4, 0]}]}, {"in": "3", "out": "3", "mem": [{"at": "so", "bytes": [3, 0]}, {"at": "pSo", "bytes": [4, 0]}]}, {"in": "5", "out": "5", "mem": [{"at": "so", "bytes": [5, 0]}, {"at": "pSo", "bytes": [4, 0]}]}, {"in": "1", "out": "1", "mem": [{"at": "so", "bytes": [1, 0]}, {"at": "pSo", "bytes": [4, 0]}]}]}, {"t": "Cộng hai chữ số vào word", "d": "Đọc lần lượt hai phím chữ số a và b (0–9) bằng INT 21h hàm 08h. Ghi vào biến word tong giá trị 1000 + a + b (1000…1018). Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: cộng hai chữ số vào một số word\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DW      ?                       ; 1000 + a + b\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     tong, 1000              ; chưa cộng a, b\n; Viết code ở đây: đọc hai phím chữ số a, b\n; rồi tong = 1000 + a + b\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "12", "mem": [{"at": "tong", "bytes": [235, 3]}]}, {"in": "00", "mem": [{"at": "tong", "bytes": [232, 3]}]}, {"in": "99", "mem": [{"at": "tong", "bytes": [250, 3]}]}, {"in": "90", "mem": [{"at": "tong", "bytes": [241, 3]}]}, {"in": "09", "mem": [{"at": "tong", "bytes": [241, 3]}]}, {"in": "47", "mem": [{"at": "tong", "bytes": [243, 3]}]}]}, {"t": "Ghi 4 biến word nhanh hơn", "d": "Đọc một phím chữ số 0–9 bằng INT 21h hàm 08h và ghi giá trị của nó (dạng word, byte cao bằng 0) vào cả 4 biến v1, v2, v3, v4 (giữ nguyên khai báo DW 0FFFFh). Code mẫu cho kết quả đúng nhưng ghi mỗi biến hai lần, lần sau bằng số tức thời. Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: ghi một chữ số vào 4 biến word\n; Bản này đúng nhưng chậm và dài: mỗi biến ghi 2 lần,\n; lần sau ghi số tức thời vào ô nhớ. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nv1      DW      0FFFFH\nv2      DW      0FFFFH\nv3      DW      0FFFFH\nv4      DW      0FFFFH\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     BYTE PTR v1, AL\n        MOV     BYTE PTR v1+1, 0\n        MOV     BYTE PTR v2, AL\n        MOV     BYTE PTR v2+1, 0\n        MOV     BYTE PTR v3, AL\n        MOV     BYTE PTR v3+1, 0\n        MOV     BYTE PTR v4, AL\n        MOV     BYTE PTR v4+1, 0\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "0", "mem": [{"at": "v1", "bytes": [0, 0]}, {"at": "v2", "bytes": [0, 0]}, {"at": "v3", "bytes": [0, 0]}, {"at": "v4", "bytes": [0, 0]}]}, {"in": "9", "mem": [{"at": "v1", "bytes": [9, 0]}, {"at": "v2", "bytes": [9, 0]}, {"at": "v3", "bytes": [9, 0]}, {"at": "v4", "bytes": [9, 0]}]}, {"in": "5", "mem": [{"at": "v1", "bytes": [5, 0]}, {"at": "v2", "bytes": [5, 0]}, {"at": "v3", "bytes": [5, 0]}, {"at": "v4", "bytes": [5, 0]}]}, {"in": "1", "mem": [{"at": "v1", "bytes": [1, 0]}, {"at": "v2", "bytes": [1, 0]}, {"at": "v3", "bytes": [1, 0]}, {"at": "v4", "bytes": [1, 0]}]}, {"in": "7", "mem": [{"at": "v1", "bytes": [7, 0]}, {"at": "v2", "bytes": [7, 0]}, {"at": "v3", "bytes": [7, 0]}, {"at": "v4", "bytes": [7, 0]}]}], "perf": {"cycles": 175, "bytes": 32}}]);

makeQuiz("quiz9","score9",[{"q": "Biến <code>bang DW 0050h<\/code> nằm ở DS:0010h. Sau hai lệnh sau, AX và BX bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     AX, bang\n        MOV     BX, OFFSET bang<\/pre>", "o": ["AX = 0010h (địa chỉ), BX = 0050h (nội dung)", "AX = 0050h, BX = 0050h vì cùng tên biến", "AX = 0050h (nội dung), BX = 0010h (địa chỉ)", "AX = 0010h, BX = 0010h vì cùng tên biến"], "a": 2, "e": "MOV AX, bang đọc ô nhớ DS:0010h nên AX là nội dung 0050h. OFFSET bang là hằng 0010h tính lúc dịch nên MOV BX, OFFSET bang chỉ nạp số tức thời (Ví dụ 5)."}, {"q": "Dòng nào bị trình dịch báo lỗi?", "o": ["<code>MOV BYTE PTR [BX], 5<\/code>", "<code>MOV [BX], 5<\/code>", "<code>MOV [BX], AL<\/code>", "<code>MOV AL, [BX]<\/code>"], "a": 1, "e": "Ở MOV [BX], 5 không bên nào cho biết kích thước: [BX] không có kiểu, 5 vừa byte vừa word. Khi một bên là thanh ghi (AL) thì kích thước theo thanh ghi đó, nên hai dòng có AL hợp lệ."}, {"q": "Biến <code>so DW 01FFh<\/code>. Sau lệnh <code>INC BYTE PTR so<\/code>, word <code>so<\/code> bằng bao nhiêu?", "o": ["0200h: tăng cả word như INC so", "01FFh: lệnh không đổi ô nhớ khi có PTR", "0000h: tràn 8 bit làm xóa cả word", "0100h: byte thấp FFh thành 00h, byte cao giữ 01h"], "a": 3, "e": "BYTE PTR biến lệnh thành INC 1 byte (mã FE): chỉ byte thấp ở địa chỉ so đổi FFh → 00h, không có nhớ sang byte cao. INC so (word, mã FF) mới cho 0200h (Ví dụ 2)."}, {"q": "Theo bảng thời gian lệnh 8086, <code>MOV AX, so<\/code> mất 10 chu kỳ còn <code>MOV DX, so<\/code> mất 14. Vì sao?", "o": ["DX là thanh ghi dữ liệu cổng nên đọc bộ nhớ chậm hơn", "AX có dạng ngắn A1 với địa chỉ trực tiếp, không cộng thời gian EA", "Lệnh với DX phải đọc bộ nhớ hai lần cho hai nửa", "Biến so nằm ở địa chỉ lẻ khi nạp vào DX"], "a": 1, "e": "MOV AX, so dùng mã A1 + địa chỉ (3 byte, 10 chu kỳ). Các thanh ghi khác dùng dạng ModR/M 8B 16 + địa chỉ (4 byte): 8 + EA 6 = 14. Cả hai chỉ đọc một word, địa chỉ như nhau."}, {"q": "Học viên viết <code>MOV AL, [60h]<\/code> để đọc ô nhớ DS:0060h và dịch bằng MASM. Phát biểu nào đúng?", "o": ["Mọi trình dịch đều đọc ô nhớ DS:0060h nên cách viết này an toàn", "Lệnh đọc cổng 60h vì số trong ngoặc vuông là số hiệu cổng", "Lệnh bị báo lỗi vì 8086 không có địa chỉ trực tiếp bằng hằng số", "MASM hiểu [60h] là số 60h nên AL = 60h; viết DS:[60h] mới đọc ô nhớ"], "a": 3, "e": "Theo tài liệu MASM, hằng số trong ngoặc vuông không có tiền tố đoạn được coi là số tức thời. NASM và trình mô phỏng của khóa lại hiểu là ô nhớ, nên cách viết này cho kết quả khác nhau giữa các trình dịch. Viết DS:[60h] (hoặc dùng tên biến) thì chắc chắn là ô nhớ."}]);

